require_once dirname(__DIR__).'/public/media-store.php';
if (($_GET['p']??'')==='ai_live') {
    header('Content-Type: application/json; charset=utf-8');
    requireAdminPage('ai');
    session_write_close();
    try { echo json_encode(aiAdmin('/v1/admin/ai/live'),JSON_UNESCAPED_UNICODE|JSON_THROW_ON_ERROR); }
    catch (Throwable) { http_response_code(503); echo json_encode(['error'=>'实时统计暂不可用。'],JSON_UNESCAPED_UNICODE); }
    exit;
}

if (($_GET['p']??'')==='feedback_media') {
    requireAdminPage('feedback');
    try { $media=fbMedia128($db,fbID128($_GET['id']??null),null); session_write_close(); fbServe128($media); }
    catch(Throwable $error) { http_response_code(404); exit('附件不可用。'); }
}
if (($_GET['p']??'')==='photo') {
    // Member meal photos are among the most sensitive synced content; viewing is
    // gated on the users_sensitive scope (super_admin/operator), not just page access.
    requireAdminWrite('member_photo');
    $uid=(int)($_GET['id']??0); $media=strtolower((string)($_GET['media']??''));
    if (!preg_match('/^[a-f0-9-]{36}\.jpg$/D',$media) || !query('SELECT 1 FROM user_media WHERE user_id=? AND media_id=?',[$uid,$media])->fetchColumn()) { http_response_code(404); exit; }
    $directory=dirname(__DIR__).'/media/'.$uid;
    try { $mediaLock=mediaStoreLockAcquire($db,$uid,$media); }
    catch (Throwable) { http_response_code(503); exit; }
    mediaStoreRecover($db,$uid,$directory,$media,true);
    $path=mediaStoreResolve($directory,$media);
    if ($path===null) { mediaStoreLockRelease($db,$mediaLock); http_response_code(404); exit; }
    header('Content-Type: image/jpeg'); readfile($path); mediaStoreLockRelease($db,$mediaLock); exit;
}
if (($_GET['p']??'')==='reward_photo') {
    requireAdminPage('club');
    $rewardId=(int)($_GET['reward']??0);
    $row=$rewardId?query('SELECT image_path FROM club_rewards WHERE id=?',[$rewardId])->fetch():null;
    $name=$row['image_path']??'';
    if ($name===null || $name==='' || basename($name)!==$name) { http_response_code(404); exit; }
    $path=dirname(__DIR__).'/admin-media/'.$name;
    if (!is_file($path)) { http_response_code(404); exit; }
    header('Content-Type: '.mime_content_type($path)); readfile($path); exit;
}
if (($_GET['p']??'')==='catalog_photo') {
    if (!adminCanViewPage('badges') && !adminCanViewPage('gifts')) requireAdminPage('badges');
    $catalogId=(int)($_GET['id']??0);
    $row=$catalogId?query('SELECT image_path,kind FROM club_reward_catalog WHERE id=?',[$catalogId])->fetch():null;
    if ($row) requireAdminPage($row['kind']==='physical'?'gifts':'badges');
    $name=$row['image_path']??'';
    if ($name===null || $name==='' || basename($name)!==$name) { http_response_code(404); exit; }
    $path=dirname(__DIR__).'/admin-media/'.$name;
    if (!is_file($path)) { http_response_code(404); exit; }
    header('Content-Type: '.mime_content_type($path)); readfile($path); exit;
}
