  <?php $clubPage=max(1,(int)($_GET['page']??1));$seasonTotal=(int)query('SELECT COUNT(*) FROM club_seasons')->fetchColumn();$seasons=query('SELECT s.*,(SELECT COUNT(*) FROM club_enrollments e WHERE e.season_id=s.id) joined,(SELECT COUNT(*) FROM club_reward_claims c WHERE c.season_id=s.id) claims,(SELECT COUNT(*) FROM club_virtual_grants g WHERE g.season_id=s.id) grants FROM club_seasons s ORDER BY s.starts_on DESC,s.id DESC LIMIT 21 OFFSET '.(($clubPage-1)*20))->fetchAll();$clubMore=count($seasons)>20;$seasons=array_slice($seasons,0,20);$selectedId=(int)($_GET['season']??0);$season=$selectedId?query('SELECT s.*,(SELECT COUNT(*) FROM club_enrollments e WHERE e.season_id=s.id) joined,(SELECT COUNT(*) FROM club_reward_claims c WHERE c.season_id=s.id) claims,(SELECT COUNT(*) FROM club_virtual_grants g WHERE g.season_id=s.id) grants FROM club_seasons s WHERE s.id=?',[$selectedId])->fetch():null;$tasks=$season?query('SELECT * FROM club_tasks WHERE season_id=? ORDER BY sort_order,id',[$selectedId])->fetchAll():[];$rewards=$season?query('SELECT * FROM club_rewards WHERE season_id=? ORDER BY sort_order,id',[$selectedId])->fetchAll():[];$claims=$pagePanel==='season-claims'?query('SELECT c.*,u.phone account_phone,r.title reward_title,s.title season_title FROM club_reward_claims c JOIN users u ON u.id=c.user_id LEFT JOIN profiles p ON p.user_id=u.id JOIN club_rewards r ON r.id=c.reward_id JOIN club_seasons s ON s.id=c.season_id ORDER BY FIELD(c.status,"pending","confirmed","packing","problem","shipped","delivered","cancelled"),c.created_at DESC,c.id DESC LIMIT 21 OFFSET '.(($clubPage-1)*20))->fetchAll():[];$claimsMore=count($claims)>20;$claims=array_slice($claims,0,20);$catalogOptions=query('SELECT * FROM club_reward_catalog WHERE active=1 ORDER BY kind,name')->fetchAll();$statusLabels=['draft'=>'草稿','published'=>'已发布','archived'=>'已归档','pending'=>'待确认','confirmed'=>'已确认','packing'=>'打包中','shipped'=>'已发货','delivered'=>'已送达','problem'=>'需处理','cancelled'=>'已取消']; ?>



  <div class="metrics"><?php foreach([['成长季',$seasonTotal,'累计创建'],['本期参与',$season['joined']??0,'已加入成员'],['实物申领',$season['claims']??0,'所选成长季'],['待履约',query("SELECT COUNT(*) FROM club_reward_claims WHERE status IN ('pending','confirmed','packing','problem')")->fetchColumn(),'需要运营处理']] as [$label,$value,$hint]):?><article><span class="muted"><?=$label?></span><b><?=safeNumber($value)?></b><small><?=$hint?></small></article><?php endforeach?></div>
