  <?php if($seasonRow['status']==='draft'):?><form method="post" data-confirm="发布后任务和奖励规则将锁定，确认发布？"><?php csrfField()?><input type="hidden" name="action" value="club_season_publish"><input type="hidden" name="season_id" value="<?=$seasonRowId?>"><button>发布</button></form><?php elseif($seasonRow['status']==='published'):?><form method="post" data-confirm="确认下架这一期成长季？历史记录会保留。"><?php csrfField()?><input type="hidden" name="action" value="club_season_archive"><input type="hidden" name="season_id" value="<?=$seasonRowId?>"><button class="danger">下架</button></form><?php endif?><?php if((int)$seasonRow['joined']===0 && (int)$seasonRow['claims']===0 && (int)$seasonRow['grants']===0):?><form method="post" data-confirm="确认彻底删除这一期成长季？删除后无法恢复。"><?php csrfField()?><input type="hidden" name="action" value="club_season_delete"><input type="hidden" name="season_id" value="<?=$seasonRowId?>"><button class="danger">彻底删除</button></form><?php endif?></td></tr><?php endforeach?></tbody></table></div></section>
