  <?php $rewardsByTask=[];foreach($rewards as $rewardRow){$rewardsByTask[(int)$rewardRow['task_id']]=$rewardRow;}?><h3>任务与对应奖励</h3><?php foreach($tasks as $i=>$task):$reward=$rewardsByTask[(int)$task['id']]??null;?><div class="record"><div class="profile-grid"><label>任务名称<input name="task_title[<?=(int)$task['id']?>]" value="<?=h($task['title'])?>" <?=$editable?'':'disabled'?>></label><label>目标次数<input type="number" min="1" max="31" name="task_target[<?=(int)$task['id']?>]" value="<?=(int)$task['target']?>" <?=$editable?'':'disabled'?>></label><label>统计方式<select name="task_metric[<?=(int)$task['id']?>]" <?=$editable?'':'disabled'?>><?php foreach(['training_days'=>'完成训练日','meal_days'=>'饮食记录日','weekly_reviews'=>'周复盘次数','meal_records'=>'饮食记录次数','daily_reports'=>'AI 日报次数','health_days'=>'健康同步日'] as $metricKey=>$metricLabel):?><option value="<?=$metricKey?>" <?=$task['metric']===$metricKey?'selected':''?>><?=$metricLabel?></option><?php endforeach?></select></label></div><label>任务说明<input name="task_detail[<?=(int)$task['id']?>]" value="<?=h($task['detail'])?>" <?=$editable?'':'disabled'?>></label><?php if($reward):?><?=badgePreview($reward,'reward_photo')?><label>绑定徽章 / 礼品库<select name="reward_catalog_id[<?=(int)$reward['id']?>]" <?=$editable?'':'disabled'?>><option value="">使用当前自定义奖励</option><?php foreach($catalogOptions as $catalogOption):?><option value="<?=(int)$catalogOption['id']?>" <?=(int)($reward['catalog_id']??0)===(int)$catalogOption['id']?'selected':''?>><?=h($catalogOption['name'])?> · <?=h($catalogOption['kind'])?></option><?php endforeach?></select></label><div class="reward-image-row"><?php if(!empty($reward['image_path'])):?><img class="reward-image-preview" src="?p=reward_photo&amp;reward=<?=(int)$reward['id']?>" alt="实物礼品照片"><?php else:?><div class="reward-image-empty">尚未上传实物照片</div><?php endif?><?php if($editable):?><label>实物照片<input type="file" name="reward_image[<?=(int)$reward['id']?>]" accept="image/jpeg,image/png,image/webp"></label><?php endif?